// Minimal endless‑runner based on IDEA.md
(function(){
  const canvas = document.getElementById('game');
  if(!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 300;
  const H = canvas.height = canvas.clientHeight || 150;

  // lanes (three equally spaced)
  const laneCount = 3;
  const laneWidth = W / laneCount;
  const playerSize = 20;
  let playerLane = 1; // 0:left,1:center,2:right
  const playerY = H - playerSize - 10;

  // blocks
  const blocks = [];
  const blockSize = 20;
  const blockSpeed = 2; // pixels per frame
  const spawnInterval = 800; // ms
  let lastSpawn = 0;

  let startTime = null;
  const maxTime = 120000; // 2 minutes
  let score = 0;
  let running = true;

  function spawnBlock(){
    const lane = Math.floor(Math.random()*laneCount);
    blocks.push({lane, y: -blockSize});
  }

  function update(dt){
    if(!running) return;
    const now = performance.now();
    if(!startTime) startTime = now;
    const elapsed = now - startTime;
    if(elapsed >= maxTime){ running = false; alert('Time up! Score: '+Math.floor(score)); return; }
    // spawn
    if(now - lastSpawn > spawnInterval){
      spawnBlock();
      lastSpawn = now;
    }
    // move blocks
    for(let i=blocks.length-1;i>=0;i--){
      const b = blocks[i];
      b.y += blockSpeed;
      // collision
      const px = laneWidth*playerLane + laneWidth/2 - playerSize/2;
      const py = playerY;
      if(b.lane===playerLane && b.y+blockSize>py && b.y<py+playerSize){
        running = false;
        alert('Game Over! Score: '+Math.floor(score));
        return;
      }
      // remove off‑screen
      if(b.y>H) blocks.splice(i,1);
    }
    // score based on distance (time)
    score = elapsed/10; // arbitrary scaling
  }

  function draw(){
    ctx.clearRect(0,0,W,H);
    // draw grid lines
    ctx.strokeStyle = 'rgba(0,255,255,0.2)';
    for(let i=1;i<laneCount;i++){
      ctx.beginPath();
      ctx.moveTo(i*laneWidth,0);
      ctx.lineTo(i*laneWidth,H);
      ctx.stroke();
    }
    // draw player
    ctx.fillStyle = '#0ff';
    const px = laneWidth*playerLane + laneWidth/2 - playerSize/2;
    ctx.fillRect(px, playerY, playerSize, playerSize);
    // draw blocks
    ctx.fillStyle = '#f0f';
    blocks.forEach(b=>{
      const x = laneWidth*b.lane + laneWidth/2 - blockSize/2;
      ctx.fillRect(x, b.y, blockSize, blockSize);
    });
    // draw score
    ctx.fillStyle = '#fff';
    ctx.font = '14px monospace';
    ctx.fillText('Score: '+Math.floor(score),10,20);
  }

  function loop(timestamp){
    if(running){
      const dt = timestamp - (lastRender||timestamp);
      update(dt);
      draw();
      lastRender = timestamp;
      requestAnimationFrame(loop);
    }
  }
  // lane change on click/tap
  canvas.addEventListener('click',()=>{
    if(!running) return;
    playerLane = (playerLane + 1) % laneCount;
  });
  // start loop
  requestAnimationFrame(loop);
})();
